    @strawberry.field
    async def users(self, info, limit: int = 10, offset: int = 0) -> List[User]:
        db = info.context["db"]
        return db.query(UserModel).offset(offset).limit(limit).all()

    @strawberry.field
    async def user(self, info, id: int) -> Optional[User]:
        db = info.context["db"]
        return db.query(UserModel).filter(UserModel.id == id).first()

    @strawberry.field
    async def posts(
        self,
        info,
        limit: int = 10,
        offset: int = 0,
        search: Optional[str] = None
    ) -> List[Post]:
        db = info.context["db"]
        query = db.query(PostModel)
        if search:
            query = query.filter(PostModel.title.ilike(f"%{search}%"))
        return query.offset(offset).limit(limit).all()

@strawberry.type
class Mutation:
    @strawberry.mutation
    async def create_post(self, info, input: CreatePostInput) -> Post:
        db = info.context["db"]
        user = info.context["user"]

        if not user:
            raise Exception("Authentication required")

        post = PostModel(
            title=input.title,
            content=input.content,
            author_id=user.id
        )
        db.add(post)
        db.commit()
        db.refresh(post)
        return post

    @strawberry.mutation
    async def delete_post(self, info, id: int) -> bool:
        db = info.context["db"]
        user = info.context["user"]

        post = db.query(PostModel).filter(PostModel.id == id).first()
        if not post:
            raise Exception("Post not found")
        if post.author_id != user.id:
            raise Exception("Not authorized")

        db.delete(post)
        db.commit()
        return True

